metric.metric_source:
def metric(data: pd.DataFrame) -> float:
    import numpy as np

    agree_match = []
    disagree_match = []

    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        disc_cues = []
        for i in range(5):
            if a[i] > b[i]:
                disc_cues.append(0)
            elif b[i] > a[i]:
                disc_cues.append(1)

        if len(disc_cues) >= 2:
            first = disc_cues[0]
            second = disc_cues[1]

            chose_first = (resp == first)

            if first == second:
                agree_match.append(chose_first)
            else:
                disagree_match.append(chose_first)

    if len(agree_match) == 0 or len(disagree_match) == 0:
        return 0.0

    return float(np.mean(agree_match) - np.mean(disagree_match))

